INSERT INTO "question_groups" ("id", "assessment_section_id", "question_bank_id", "title", "stimulus_type", "stimulus_content", "order", "created_at", "updated_at") VALUES (222, 105, NULL, E'Stimulus Narasi 3', E'text', E'Jajar genjang PQRS memiliki luas 20. Jika T terletak pada $\\overline{QR}$ sehingga $\\overline{ST}$ tegak lurus terhadap $\\overline{QR}$.
INSERT INTO "question_groups" ("id", "assessment_section_id", "question_bank_id", "title", "stimulus_type", "stimulus_content", "order", "created_at", "updated_at") VALUES (223, 105, NULL, E'Stimulus Narasi 4', E'text', E'Garis $l$ melalui titik B pada persegi ABCD dan tegak lurus terhadap diagonal $\\overline{BD}$.
INSERT INTO "question_groups" ("id", "assessment_section_id", "question_bank_id", "title", "stimulus_type", "stimulus_content", "order", "created_at", "updated_at") VALUES (224, 105, NULL, E'Stimulus Narasi 5', E'text', E'Persegi ABCD memuat E pada $\\overline{AD}$ sehingga gradien $\\overline{BE}$ sama dengan 2.
