INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (529, 64, NULL, NULL, E'binary_matrix', E'Jika 9 = VITQJUMA dan 10 = PCTCXMA, maka 11 =........', E'* Angka diubah menjadi kata dalam bahasa Indonesia lalu dibalik urutan hurufnya:
