(2) Banyak siswa yang mengakses media sosial selama jam pelajaran sekolah.
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (531, 64, NULL, NULL, E'mcq_single', E'Antonim dari MANDIRI adalah....', E'Mandiri berarti berdiri sendiri atau tidak bergantung pada orang lain. Lawan kata (antonim) dari mandiri adalah dependen (tergantung pada pihak lain).', 1, E'{"labels":["Benar","Salah"]}', 16, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (532, 64, NULL, NULL, E'mcq_single', E'AUDITING : PEMBUKUAN = ...', E'Auditing dilakukan untuk memeriksa dan menilai pembukuan. Secara analogi yang setara, evaluasi dilakukan untuk memeriksa dan menilai kebijakan.', 1, E'{"labels":["Benar","Salah"]}', 17, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (533, 64, NULL, NULL, E'mcq_single', E'Pilihlah kata yang janggal di antara pilihan kata berikut adalah.....', E'Genteng, tembok, lantai, dan pintu merupakan elemen struktural pembentuk bangunan/rumah, sedangkan meja adalah perabot (furnitur) pengisi ruangan.', 1, E'{"labels":["Benar","Salah"]}', 18, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
