INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (537, 64, NULL, NULL, E'mcq_single', E'Ada lima buah balon dengan warna dan ukuran berbeda. Balon biru lebih besar daripada balon kuning. Balon ungu lebih kecil daripada balon putih. Balon kuning lebih besar daripada balon putih. Balon hijau lebih besar daripada balon kuning, tetapi lebih kecil dari satu balon lainnya.
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (538, 65, 47, NULL, E'mcq_single', E'Inti persoalan dalam paragraf pertama pada teks tersebut adalah....', E'Inti persoalan dalam paragraf pertama pada teks tersebut adalah persoalan politik dan kebertahanan (kestabilan) kehidupan beragama dan berbangsa sebagaimana dirangkum pada kalimat (1) dan (4).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (539, 65, 47, NULL, E'mcq_single', E'Pesan yang terkandung dalam paragraf kedua pada teks tersebut adalah....', E'Paragraf kedua menjelaskan bahwa kebencian dan kesenjangan yang bekerja melalui jejaring sosial, kebijakan negara, serta keterlibatan sebagian masyarakat secara tidak langsung menjadi faktor menguatnya gerakan radikalisme dan terorisme.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (540, 65, 47, NULL, E'mcq_single', E'Berdasarkan tulisan di atas, analogi yang sama dengan pernyataan bahwa “Ada kebencian dan kesenjangan yang terpelihara dan bekerja melalui berbagai jejaring sosial bahkan melalui kebijakan negara.” adalah....', E'Analogi yang tepat yaitu amanat : novel karena amanat disampaikan melalui media novel sebagai karya sastra, sama halnya dengan kebencian dan kesenjangan yang disampaikan atau bekerja melalui media jejaring sosial.', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (541, 65, 48, NULL, E'mcq_weighted', E'Pada teks di atas ada penggunaan diksi yang kurang tepat terletak pada kalimat....', E'Apabila melihat konteks kalimat sebelum dan sesudahnya yang membahas kerusakan sistem lingkungan secara menyeluruh (termasuk air, udara, dan iklim), penggunaan istilah "degradasi lahan" pada kalimat (3) kurang tepat karena maknanya terlalu sempit. Istilah yang lebih tepat adalah "degradasi lingkungan".', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (542, 65, 48, NULL, E'mcq_single', E'Makna degradasi pada kalimat 3 teks di atas ialah....', E'Menurut KBBI, degradasi bermakna kemunduran, kemerosotan, atau penurunan (tentang mutu, moral, pangkat, dan sebagainya).', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (543, 65, 49, NULL, E'mcq_single', E'Judul yang tepat untuk melengkapi paragraf di atas adalah.... (detikhealth)', E'Keseluruhan kalimat dalam paragraf menguraikan berbagai efek positif mandi air dingin bagi tubuh (membantu bangun pagi, meningkatkan sirkulasi darah, meredakan nyeri otot, dan menyehatkan kulit serta rambut), sehingga judul yang paling tepat adalah Manfaat Mandi Air Dingin.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (544, 65, 49, NULL, E'mcq_single', E'Kata berimbuhan yang salah digunakan dalam paragraf tersebut adalah.... (detikhealth)', E'Kata "dikenai" pada kalimat (2) tidak tepat secara tata bahasa dan makna aktif-pasifnya; kata yang tepat seharusnya adalah "mengenai" ("Ketika semprotan dingin mengenai tubuh, ada sedikit kejutan").', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (545, 65, 49, NULL, E'mcq_single', E'Makna kata *ini* pada kalimat 3 merujuk pada.... (detikhealth)', E'Pada kalimat (3) "Guncangan ini meningkatkan asupan oksigen, detak jantung, dan kewaspadaan", kata penunjuk "ini" merujuk pada efek dari semprotan air dingin pada kalimat sebelumnya.', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (546, 65, 49, NULL, E'mcq_single', E'Kata berimbuhan yang tepat untuk melengkapi bagian rumpang pada kalimat 4 adalah.... (detikhealth)', E'Bagian rumpang pada kalimat (4) membutuhkan verba kausatif yang menghubungkan stimulus air dingin dengan respons sirkulasi darah, yaitu "menyebabkan" ("...maka akan menyebabkan darah bersirkulasi dengan kecepatan lebih cepat...").', 1, E'{"labels":["Benar","Salah"]}', 4, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (547, 65, 49, NULL, E'mcq_single', E'Kata berimbuhan yang tepat untuk melengkapi bagian rumpang pada kalimat 5 adalah.... (detikhealth)', E'Karena air dingin bersifat regeneratif dan membuat otot rileks setelah latihan berat, maka mandi air dingin berfungsi membantu "mengurangi" nyeri otot setelah latihan intensif.', 1, E'{"labels":["Benar","Salah"]}', 5, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (548, 65, 49, NULL, E'mcq_single', E'Kata yang tepat untuk melengkapi bagian rumpang pada kalimat 6 adalah....... (detikhealth)', E'Bagian setelah rumpang pada kalimat (6) ("kesehatan kulit dan rambut yang lebih bercahaya") merupakan rincian contoh dari manfaat mandi air dingin lainnya, sehingga kata penghubung pemerincian yang tepat adalah "seperti".', 1, E'{"labels":["Benar","Salah"]}', 6, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (549, 65, 50, NULL, E'mcq_single', E'Judul yang paling tepat untuk menggambarkan isi dari teks di atas adalah.... (Sanit, Arbi. 2015. Jurnal Politik Vol 1, No. 1: 155—175)', E'Judul harus mewakili keseluruhan isi teks. Teks di atas menguraikan perjalanan sistem demokrasi dan sistem politik di Indonesia hingga tahap konsolidasi serta penyempurnaan demokrasi presidensial. Dengan demikian, judul yang tepat adalah Pematangan Demokrasi dan Politik Indonesia.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (550, 65, 50, NULL, E'mcq_single', E'Kata berimbuhan yang tidak tepat pada paragraf kedua adalah...... (Sanit, Arbi. 2015. Jurnal Politik Vol 1, No. 1: 155—175)', E'Kata dasar dari bentukan tersebut dalam KBBI adalah "baru" (bukan "baharu"), sehingga bentuk berimbuhan yang baku adalah "memperbarui", bukan "memperbaharui".', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (551, 65, 50, NULL, E'mcq_single', E'Penggunaan kata yang salah di paragraf pertama adalah....... (Sanit, Arbi. 2015. Jurnal Politik Vol 1, No. 1: 155—175)', E'Berdasarkan kunci sistem sumber adalah B, namun secara ejaan baku KBBI penggunaan kata yang salah pada paragraf pertama adalah "komperhensif" (opsi E) yang seharusnya ditulis "komprehensif".', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (552, 65, NULL, NULL, E'mcq_single', E'Bacalah teks berikut!
(1) Menteri Pendidikan dan Kebudayaan (Mendikbud), Nadiem Makarim, menyebutkan bahwa prioritas Merdeka Belajar 2021 akan berfokus pada beberapa hal. (2) Fokus pertama meliputi pembiayaan pendidikan yang akan menyasar pemilik Kartu Indonesia Pintar (KIP) Kuliah dengan target 1,095 juta mahasiswa dan KIP Sekolah dengan target 17,9 juta siswa. (3) “Kemudian, ada bantuan pemerintah kepada 13 SILN dan 2.236 lembaga,” ungkap Nadiem dalam acara Taklimat Media Awal Tahun 2021. (4) Dengan adanya hal itu, program-program yang dijalankan diharapkan dapat berjalan lancar. (5) Fokus kedua adalah program *digitalisasi* sekolah dan medium pembelajaran melalui empat sistem penguatan platform digital, dan delapan layanan terpadu Kemendikbud. (6) Fokus ketiga adalah pembinaan peserta didik, prestasi, talenta, dan penguatan karakter. (7) Prioritas ini […] diciptakan melalui tiga layanan pendampingan advokasi dan sosialisasi penguatan karakter. (8) Selain itu, prioritas ini diciptakan dengan beberapa cara, seperti pembinaan peserta didik oleh 345 pemerintah daerah serta peningkatan prestasi, manajemen talenta kepada 13.505 pelajar, dan sebagainya. (9) Sementara itu, untuk fokus keempat, Kemendikbud menargetkan adanya pendidikan kepada 19.624 guru penggerak tahun ini. (10) Lalu, akan ada sertifikasi terhadap 10 ribu guru dan tenaga kependidikan. (11) Selain itu, ada pula perekrutan guru PPPK oleh 548 pemerintah daerah serta penjaminan mutu sekolah penggerak dan organisasi penggerak kepada 20.438 orang guru.
(Diadaptasi dari kompas.com pada 6 Januari 2021)
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (553, 65, NULL, NULL, E'mcq_single', E'(1) Masyarakat sudah mengetahui bahwa program *reality show* dituding *setting*-an belaka atau penuh dengan *gimmick*. (2) Artinya, acara itu tidak benar-benar menampilkan realitas. (3) Beberapa waktu lalu, warganet membicarakan salah satu program *reality show* karena sempat terjadi keteledoran. (4) *Clip on* yang dipakai salah satu narasumbernya jatuh. (5) Oleh karena itu, jika sesuai jalan cerita, narasumber yang baru ditemui saat itu juga tak seharusnya menggunakan *clip on*.
(Diadaptasi dari: [http://tirto.id/](http://tirto.id/))
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (554, 65, NULL, NULL, E'mcq_single', E'Bacalah teks berikut!
(1) Menteri Dalam Negeri, Tito Karnavian, mengatakan bahwa PPKM level 3 se-Indonesia pada masa libur Nataru yang dibatalkan pemerintah diganti dengan pembatasan kegiatan masyarakat pada masa Nataru. (2) Kebijakan itu diubah agar pembatasan yang diterapkan pada masa Nataru berlaku secara spesifik selama 24 Desember 2021 hingga 2 Januari 2022, bergantung situasi di masing-masing daerah. (3) Tito menyampaikan ada beberapa faktor yang membuat pemerintah membatalkan rencana PPKM Level 3 se-Indonesia pada masa libur Nataru.
(4) Pertama, situasi pandemi Covid-19 di Indonesia dalam beberapa waktu terakhir relatif landai dan angka penularannya pun terbilang rendah. (5) Berdasarkan survei yang dilakukan Kementerian Kesehatan, antibodi masyarakat sudah terbilang tinggi. (6) Bahkan, Tito menyebut ada kemungkinan masyarakat di sembilan daerah aglomerasi telah mengalami kekebalan kelompok. (7) Kondisi daerah juga selalu dinamis dan tingkat vaksinasi yang meningkat. (8) Meski berubah istilah, pemerintah akan tetap menerapkan pembatasan, misalnya pengunjung mal dibatasi maksimum 75 persen dari kapasitas. (9) Hanya warga yang sudah menjalani vaksinasi dua dosis yang dapat beraktivitas di tempat publik dan penerapan aplikasi Peduli-Lindungi di ruang publik.
(10) Ketua Bidang Penanganan Kesehatan Satgas Covid-19 Nasional, Brigjen TNI Purn. dr. Alexander K. Ginting, Sp.P(K), FCCP mengatakan bahwa ketentuan PPKM berpedoman pada Instruksi Menteri Dalam Negeri Nomor 62 Tahun 2021 tentang Pencegahan dan Penanggulangan *CoronaVirus Disease* 2019 pada Saat Natal Tahun 2021 dan Tahun Baru Tahun 2022. (11) Syarat perjalanan jarak jauh dalam negeri saat Nataru adalah wajib vaksinasi lengkap dan hasil antigen negatif maksimal 1 × 24 jam sebelum keberangkatan. (12) Untuk orang dewasa yang belum mendapatkan vaksinasi lengkap ataupun tidak bisa divaksin karena alasan medis tak diizinkan untuk bepergian jarak jauh. (13) Bagi anak-anak, tetap dapat melakukan perjalanan dengan syarat lebih ketat. (14) Syaratnya telah melakukan PCR yang berlaku 3 × 24 jam untuk perjalanan udara atau antigen 1 × 24 jam untuk perjalanan darat atau laut.
(Diadaptasi dari: [https://www.pikiran-rakyat.com/kolom/pr-013184102/masih-saja-pemerintah-bermain-dengan-istilah-ppkm-level-3-saat-nataru-batal?page=3](https://www.pikiran-rakyat.com/kolom/pr-013184102/masih-saja-pemerintah-bermain-dengan-istilah-ppkm-level-3-saat-nataru-batal?page=3))
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (555, 65, NULL, NULL, E'mcq_single', E'Teks berikut untuk menjawab soal di bawah ini.
(1) Pada Kamis malam, debit tinggi Sungai Batu Ganda di Kecamatan Lasusua membawa limpasan air ke permukiman warga. (2) Tidak hanya satu sungai, tetapi juga debit sungai di Kecamatan Rante Angin juga naik dan merendam permukiman warga. (3) "Tadi malam ada dua kejadian, yakni di Rante Angin dan di Sungai Batu Ganda. (4) Belum ada korban jiwa yang terdata sampai Jumat pagi,” tutur petugas BPBD Kolaka Utara. (5) Saat ini, pihak daerah setempat sedang fokus untuk mendata warga yang terkena dampak dan mendata daerah yang terisolasi. (6) Petugas BPBD Kolaka Utara dan sejumlah instansi yang terkait pun tengah mengevakuasi dan melakukan pemulihan kepada warga yang terkena dampak banjir. (7) Sebelumnya, banjir bandang dari luapan Sungai Latawaro menerjang Dusun IV, Desa Latawaro, Lambai, Kolaka Utara, pada Kamis dini hari. (8) Sebanyak tiga rumah warga terendam dan satu jembatan tidak bisa dilalui ... ada bagian jembatan yang hanyut akibat terjangan air. (9) Kepala Polsek Rante Angin, Agustian Rante Parabang, menyampaikan bahwa selain merendam rumah dan perkebunan, banjir juga memutuskan akses jembatan sehingga tidak bisa dilalui. (10) Pihaknya telah membuat jembatan darurat agar bisa dilalui kendaraan roda dua. (11) Selain itu, bronjong penahan air yang baru selesai dibangun juga rusak parah karena terkena terjangan air. (12) Bronjong tersebut diketahui baru selesai dikerjakan dengan anggaran ratusan juta. (13) Selain karena hujan deras, Agustian juga berpendapat bahwa aktivitas manusia di bagian hulu juga menyebabkan banjir turut membawa batang dan ranting pohon. (14) Hal tersebut berdampak pada meluapnya air sungai dan menyebabkan banjir bercampur lumpur.
(Yunus, Saiful Rijal. 2020. “Banjir di Kolaka Utara Meluas, Ratusan Warga Desa Batu Ganda Terisolir”. Kompas.id. Diakses dan diadaptasi pada 7 Desember 2021.)
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (556, 65, NULL, NULL, E'mcq_weighted', E'Kucing merupakan salah satu jenis hewan (1)...... yang ada di muka bumi. Selain itu, kucing juga dikenal sebagai salah satu jenis hewan (2)...... yang terkenal, selain anjing ataupun ikan cupang. Kucing sendiri mempunyai sejumlah spesies yang tersebar di seluruh dunia. Namun, menurut beberapa penelitian, spesies kucing yang paling banyak tersebar dan paling banyak dipelihara di dunia adalah kucing ras campuran atau yang dikenal dengan sebutan kucing (3)....... Jenis kucing ini memang terhitung banyak, apalagi di negara kita ini. Selain spesies kucing tersebut, terdapat pula beberapa spesies kucing ras alami yang lazim dipelihara manusia. Salah satu jenis kucing tersebut adalah kucing (4)...... yang kini mulai menjadi primadona bagi pecinta kucing.
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (557, 65, NULL, NULL, E'mcq_single', E'Di bawah ini yang merupakan kelompok kata baku.....', E'Berdasarkan KBBI, penulisan kata baku yang tepat secara keseluruhan terdapat pada opsi B: "Jenderal" (bukan jendral), "karier" (bukan karir), dan "ijazah" (bukan ijasah). Adapun ketidaktetapan pada opsi lain: analisa (seharusnya analisis), isteri (seharusnya istri), dan apotik (seharusnya apotek).', 1, E'{"labels":["Benar","Salah"]}', 10, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (558, 66, 51, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (31) **standar** adalah .... (health.kompas.com)', E'Kata "standar" tidak perlu diperbaiki karena sudah merupakan bentuk kata baku sesuai KBBI.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (559, 66, 51, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (32) **kompleks** adalah .... (health.kompas.com)', E'Kata "kompleks" sudah tepat penulisannya secara baku dan sesuai dengan konteks kalimat sehingga tidak perlu diperbaiki.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (560, 66, 51, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (33) **Di mana** adalah .... (health.kompas.com)', E'Frasa "Di mana" berfungsi untuk menanyakan tempat/posisi dan tidak baku digunakan sebagai kata penghubung di awal kalimat. Kata yang tepat untuk menggantikannya adalah "Ketika" ("Ketika anak yang mengalami stunting cenderung memiliki sistem metabolisme tubuh yang tidak optimal...").', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (561, 66, 51, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (34) **sistem** adalah .... (health.kompas.com)', E'Kata "sistem" sudah merupakan ejaan baku dalam bahasa Indonesia sehingga tidak perlu diperbaiki.', 1, E'{"labels":["Benar","Salah"]}', 4, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (562, 66, 51, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (35) **kerap** adalah .... (health.kompas.com)', E'Kata "kerap" digantikan dengan kata "sering" agar membentuk frasa baku "sering kali" yang selaras dengan laras bahasa formal pada teks.', 1, E'{"labels":["Benar","Salah"]}', 5, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (563, 66, 51, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (36) **di miliki** adalah .... (health.kompas.com)', E'Penulisan "di miliki" tidak tepat karena "di-" pada kata tersebut merupakan awalan (prefiks) pembentuk verba pasif, bukan kata depan, sehingga harus ditulis serangkai menjadi "dimiliki".', 1, E'{"labels":["Benar","Salah"]}', 6, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (564, 66, 52, NULL, E'mcq_single', E'Perbaikan yang tepat untuk frasa bercetak tebal nomor (37) **Tugu Kilometer Nol** adalah .... (pesona.travel/keajaiban)', E'Tugu Kilometer Nol merupakan nama diri geografis/tempat di Kawasan Iboih, Sukakarya, Sabang. Penulisan yang tepat untuk nama tempat adalah menggunakan huruf awal kapital pada setiap unsurnya. Dengan demikian, penulisan tersebut tidak perlu diperbaiki.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-19 20:53:00', E'2026-10-22 21:30:15', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (565, 66, 52, NULL, E'mcq_single', E'Perbaikan yang tepat untuk frasa bercetak tebal nomor (38) **Barat Indonesia** adalah .... (pesona.travel/keajaiban)', E'Kata "barat" menunjukkan arah mata angin. Petunjuk arah mata angin ditulis dengan huruf awal kapital hanya apabila menjadi bagian dari nama diri geografis/wilayah administratif (seperti Kalimantan Barat atau Jakarta Timur). Karena pada konteks ini hanya menunjukkan arah (bagian barat dari wilayah Indonesia), maka ditulis dengan huruf kecil menjadi "barat Indonesia".', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-19 20:53:00', E'2026-10-22 21:30:15', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (566, 66, 52, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (39) **sunset** adalah .... (pesona.travel/keajaiban)', E'Kata *sunset* adalah kosakata bahasa Inggris yang berarti matahari terbenam. Berdasarkan kaidah EYD, penulisan istilah bahasa asing yang belum diserap ke dalam bahasa Indonesia harus dicetak miring (*sunset*).', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (567, 66, 52, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (40) **gunung** adalah .... (pesona.travel/keajaiban)', E'Kata "gunung" merupakan istilah geografi umum yang tidak diikuti nama diri, sehingga ditulis dengan huruf awal kecil. Oleh sebab itu, penulisannya sudah tepat dan tidak perlu diperbaiki.', 1, E'{"labels":["Benar","Salah"]}', 4, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (568, 66, 52, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (41) **disini** adalah .... (pesona.travel/keajaiban)', E'Kata "di" pada "di sini" merupakan kata depan (preposisi) penunjuk tempat, sehingga penulisannya harus dipisah dari kata yang mengikutinya menjadi "di sini".', 1, E'{"labels":["Benar","Salah"]}', 5, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (569, 66, 52, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (42) **mengeksplorasi** adalah .... (pesona.travel/keajaiban)', E'Kata "mengeksplorasi" bermakna menjelajahi atau mengadakan penyelidikan di lapangan. Secara ejaan dan kesesuaian makna dalam kalimat, kata tersebut sudah tepat sehingga tidak perlu diperbaiki.', 1, E'{"labels":["Benar","Salah"]}', 6, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (570, 66, 52, NULL, E'mcq_single', E'Perbaikan yang tepat untuk frasa bercetak tebal nomor (43) **hutan wisata Sabang** adalah .... (pesona.travel/keajaiban)', E'Penulisan "Hutan Wisata Sabang" harus menggunakan huruf awal kapital pada setiap katanya karena merujuk pada nama kawasan/tempat wisata spesifik.', 1, E'{"labels":["Benar","Salah"]}', 7, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (571, 66, 53, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (44) **teknologi** adalah .... (Pestisida Organik, Winarti)', E'Dalam konteks kalimat pertama, pertanian organik lebih tepat disebut sebagai salah satu "metode" (cara kerja yang bersistem dalam melaksanakan kegiatan produksi), bukan "teknologi".', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (572, 66, 53, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (45) **agrobisnis** adalah .... (Pestisida Organik, Winarti)', E'Karena kalimat tersebut menekankan keberlanjutan secara sosial dan ekologis (hubungan timbal balik antara masyarakat dan lingkungan fisik pertaniannya), istilah yang tepat adalah "agroekosistem".', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (573, 66, 53, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (46) **dan** adalah .... (Pestisida Organik, Winarti)', E'Pasangan konjungsi korelatif untuk kata "baik" adalah "maupun" (baik ... maupun ...), bukan "dan".', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (574, 66, 53, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (47) **Selain** adalah .... (Pestisida Organik, Winarti)', E'Penggunaan konjungsi antarkalimat "Selain itu" untuk menambahkan informasi mengenai kelebihan lain dari pertanian organik sudah tepat sehingga tidak perlu diperbaiki.', 1, E'{"labels":["Benar","Salah"]}', 4, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (575, 66, 53, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (48) **modal** adalah .... (Pestisida Organik, Winarti)', E'Dukungan formal dari pemerintah terhadap suatu sistem produksi diwujudkan melalui regulasi atau "peraturan" pemerintah, sehingga kata "modal" harus diganti dengan "peraturan".', 1, E'{"labels":["Benar","Salah"]}', 5, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (576, 66, 53, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (49) **menarik** adalah .... (Pestisida Organik, Winarti)', E'Karena alasan yang dikemukakan adalah "prosesnya lamban dan hasilnya tidak elok", dari sudut pandang usaha tani hal tersebut dinilai kurang "menguntungkan" (memberi laba/manfaat ekonomi).', 1, E'{"labels":["Benar","Salah"]}', 6, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (577, 66, 53, NULL, E'mcq_single', E'Perbaikan yang tepat untuk kata bercetak tebal nomor (50) **pengendali** adalah .... (Pestisida Organik, Winarti)', E'Penggunaan kata "pengendali" dalam frasa "pengendali hama dan penyakit" sudah tepat secara diksi pertanian sehingga tidak perlu diperbaiki.', 1, E'{"labels":["Benar","Salah"]}', 7, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (578, 67, NULL, NULL, E'mcq_single', E'Jika $w, x, y, z$ adalah 4 bilangan, mana di antara yang berikut ini tidak sama dengan $w(x + y + z)$ adalah …..', E'Berdasarkan sifat distributif perkalian terhadap penjumlahan, $w(x + y + z) = wx + wy + wz$. Pilihan A, B, C, dan E bernilai sama dengan bentuk tersebut, sedangkan pilihan D ($wx + x + y + z$) tidak ekuivalen.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (579, 67, NULL, NULL, E'mcq_single', E'Jika seorang berjalan menempuh jarak $\\frac{2}{5}$ km dalam 5 menit, berapa kecepatan rata-rata perjalanan orang tersebut dalam 1 jam?', E'Jarak yang ditempuh dalam 5 menit adalah $\\frac{2}{5}$ km. Dalam 1 jam (60 menit), terdapat 12 periode waktu 5 menit ($60 \\div 5 = 12$). Maka jarak dalam 1 jam adalah $X = \\frac{2}{5} \\times 12 = 4,8$ km / jam.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (580, 67, NULL, NULL, E'mcq_single', E'Seorang siswa memperoleh nilai 91, 88, 86 dan 78 untuk empat mata pelajaran. Berapa nilai yang harus diperoleh untuk mata pelajaran kelima agar dia memperoleh nilai rata-rata 85?', E'Jumlah total nilai untuk 5 mata pelajaran dengan rata-rata 85 adalah $5 \\times 85 = 425$. Jumlah 4 mata pelajaran yang sudah ada adalah $91 + 88 + 86 + 78 = 343$. Nilai mata pelajaran kelima ($x$) adalah $343 + x = 425 \\implies x = 82$.', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (581, 67, NULL, NULL, E'mcq_single', E'Jika $2x < 8$ dan $-4 < y < 5$, manakah dari angka berikut yang tidak termasuk himpunan nilai $xy$?', E'Dari pertidaksamaan $2x < 8$, didapat $x < 4$. Dengan rentang $-4 < y < 5$, batas minimum perkalian $xy$ mendekati $-4 \\times 4 = -16$ (batas terbuka, sehingga $xy > -16$). Oleh karena itu, -32 tidak termasuk dalam himpunan nilai $xy$.', 1, E'{"labels":["Benar","Salah"]}', 4, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (582, 67, NULL, NULL, E'mcq_single', E'Luas bola yang memiliki volume sebesar $\\frac{9}{2} \\pi x^{3}\\text{ cm}^{3}$ adalah....', E'Volume bola $V = \\frac{4}{3}\\pi r^3 = \\frac{9}{2}\\pi x^3 \\implies r^3 = \\frac{27}{8}x^3 \\implies r = \\frac{3}{2}x$. Luas permukaan bola $L = 4\\pi r^2 = 4\\pi \\left(\\frac{3}{2}x\\right)^2 = 9\\pi x^2\\text{ cm}^2$.', 1, E'{"labels":["Benar","Salah"]}', 5, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (583, 67, NULL, NULL, E'mcq_single', E'Jika panjang persegi panjang adalah satu lebihnya dari lebar persegi panjang tersebut, sedangkan jika panjangnya ditambah 3 cm dan lebarnya ditambah 2 cm persegi panjang tersebut luasnya bertambah $43\\text{ cm}^2$. Luas persegi panjang mula-mula adalah....', E'Luas mula-mula $= l(l + 1) = l^2 + l$. Luas setelah terjadi perubahan $= (l + 4)(l + 2) = l^2 + 6l + 8$. Diketahui luas bertambah 43, maka $(l^2 + 6l + 8) - (l^2 + l) = 43 \\implies 5l = 35 \\implies l = 7$ dan $p = 8$. Maka luas mula-mula $= 56$.', 1, E'{"labels":["Benar","Salah"]}', 6, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (584, 67, NULL, NULL, E'mcq_single', E'Dua buah kubus panjang rusuknya berselisih 3 cm dan luas permukaannya berselisih $342\\text{ cm}^2$. Panjang rusuk kubus yang lebih besar adalah.... cm.', E'Misalkan panjang rusuk dua kubus masing-masing $a$ dan $b$. $a - b = 3$ dan selisih luas permukaan $6a^2 - 6b^2 = 342 \\implies a^2 - b^2 = 57 \\implies (a - b)(a + b) = 57 \\implies 3(a + b) = 57 \\implies a + b = 19$. Eliminasi dengan $a - b = 3$ diperoleh $a = 11$ dan $b = 8$.', 1, E'{"labels":["Benar","Salah"]}', 7, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (585, 67, NULL, NULL, E'mcq_single', E'Yudi membeli buku setiap 4 hari sekali, sedangkan Fahri membeli buku setiap 7 hari sekali. Kemarin Yudi membeli buku. Fahri akan membeli tabloid 2 hari lagi. Keduanya paling cepat akan membeli buku pada hari sama ….. hari lagi.', E'Jika hari ini dianggap 0 (nol), kemarin Yudi (-1), siklus berikutnya: +3, +7, +11, +15, +19, +23. Fahri membeli tabloid 2 hari lagi (+2), siklus berikutnya: +9, +16, +23. Maka bersama setelah 23 hari dari sekarang.', 1, E'{"labels":["Benar","Salah"]}', 8, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (586, 67, NULL, NULL, E'mcq_single', E'Antara bilangan 20 dan 116 disisipi 9 bilangan. Bilangan ini bersama dua bilangan semula membentuk deret hitung. Jumlah deret hitung adalah ……', E'Banyak suku setelah disisipi adalah $n = 2 + 9 = 11$ suku. Suku pertama $a = 20$ dan suku ke-11 ($U_{11}$) $= 116$. Jumlah deret hitung adalah:
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (587, 67, NULL, NULL, E'mcq_weighted', E'Suatu garis melalui titik (5, -1) dan mempunyai gradien $\\frac{1}{4}$. Titik koordinat berikut yang terletak pada garis tersebut adalah....
(1) (8, 0)
(2) (14, 1)
(3) (12, $\\frac{5}{4}$)
(4) (16, $\\frac{7}{4}$)', E'Persamaan garis adalah $y + 1 = \\frac{1}{4}(x - 5) \\implies y = \\frac{1}{4}x - \\frac{9}{4}$. Uji titik (4): $y = \\frac{1}{4}(16) - \\frac{9}{4} = 4 - \\frac{9}{4} = \\frac{7}{4}$ (Benar). Hanya pernyataan (4) yang benar.', 1, E'{"labels":["Benar","Salah"]}', 10, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (588, 67, NULL, NULL, E'mcq_single', E'Peluang sukses seorang pemain bola basket memasukan bola ke dalam keranjang adalah $\\frac{5}{7}$. Jika ia melemparkan bola sebanyak tiga kali, maka berapa peluang melemparkan bola satu kali sukses dan dua kali gagal adalah ……', E'Menggunakan distribusi binomial untuk 1 sukses dan 2 gagal dari 3 percobaan:
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (589, 67, NULL, NULL, E'mcq_single', E'Berdasarkan barisan berikut 4, 12, 28, 60, 196, 300, x. Maka hubungan antara kuantitas P dan Q berdasarkan informasi tersebut adalah …..
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (590, 67, NULL, NULL, E'mcq_single', E'Biaya inap sepeda motor di stasiun kereta api Medan adalah sebesar Rp24.000,00 per hari. Setiap tambahan jam berikutnya akan dikenai tarif setengah dari tarif awal. Arwin menitipkan sepeda motornya selama 3,5 hari. Biaya penitipan yang harus dibayar adalah …..', E'Biaya untuk 3,5 hari terdiri dari 1 hari pertama ditambah 2,5 hari tambahan dengan tarif setengahnya ($0,5 \\times 24.000 = 12.000$ per hari): $\\text{Biaya} = 24.000 + 2,5(12.000) = \\text{Rp}54.000,00$.', 1, E'{"labels":["Benar","Salah"]}', 13, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (591, 67, NULL, NULL, E'mcq_single', E'Di toko Pena 5 buah pulpen dan 3 buah lem berharga Rp17.700,00 sedangkan jika membeli 3 buah lem dan 2 buah pulpen yang sama, harganya adalah Rp10.950,00. Jika x adalah harga 1 buah pulpen dan y harga 1 buah lem maka......', E'Eliminasi persamaan $5x + 3y = 17.700$ dan $2x + 3y = 10.950$ menghasilkan $3x = 6.750 \\implies x = 2.250$ (pulpen).
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (592, 67, NULL, NULL, E'mcq_single', E'30 % dari 70 sama dengan berapa persen dari 200?', E'$$\\frac{30}{100} \\times 70 = \\frac{p}{100} \\times 200 \\implies 2p = 21 \\implies p = \\frac{21}{2} = 10 \\frac{1}{2}$$', 1, E'{"labels":["Benar","Salah"]}', 15, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (593, 67, NULL, NULL, E'mcq_single', E'Suatu seri: 37 – 28 – 21 – 16 – ….. Maka seri selanjutnya adalah.....', E'Pola pengurangan antar suku berkurang 2 secara konstan: $37 \\xrightarrow{-9} 28 \\xrightarrow{-7} 21 \\xrightarrow{-5} 16 \\xrightarrow{-3} 13$.', 1, E'{"labels":["Benar","Salah"]}', 16, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (594, 67, NULL, NULL, E'mcq_single', E'Bila roda berputar 9 kali maka roda kedua berputar 24 kali. Bila yang pertama berputar 27 kali, maka berapa kali perputaran roda yang kedua?', E'Perbandingan putaran roda adalah $\\frac{9}{24} = \\frac{3}{8}$. Jika roda pertama berputar 27 kali, putaran roda kedua adalah $\\frac{27 \\times 8}{3} = 72$ kali.', 1, E'{"labels":["Benar","Salah"]}', 17, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (595, 67, NULL, NULL, E'mcq_single', E'Sebuah bejana berbentuk silinder berisi air $\\frac{1}{3}$ nya. Jika ditambah air sebanyak 3 liter maka bejana ini menjadi berisi $\\frac{1}{2}$ nya. Maka kapasitas bejana adalah ….. liter.', E'$\\frac{1}{3}V + 3 = \\frac{1}{2}V \\implies 3 = \\frac{1}{2}V - \\frac{1}{3}V \\implies 3 = \\frac{1}{6}V \\implies V = 18$ liter.', 1, E'{"labels":["Benar","Salah"]}', 18, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (596, 67, NULL, NULL, E'mcq_single', E'The $\\diamond$ operations on a set of integers is defined as $a \\diamond b = \\vert{}a - b\\vert{} + 2a^3 - 5$. The value of $2 \\diamond (3 \\diamond 5)$ is …..', E'Hitung $3 \\diamond 5 = \\vert{}3 - 5\\vert{} + 2(3^3) - 5 = 2 + 54 - 5 = 51$. Selanjutnya hitung $2 \\diamond 51 = \\vert{}2 - 51\\vert{} + 2(2^3) - 5 = 49 + 16 - 5 = 60$.', 1, E'{"labels":["Benar","Salah"]}', 19, E'2026-10-19 20:53:00', E'2026-10-19 20:53:00', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (597, 67, NULL, NULL, E'mcq_single', E'Gayo Coffee menjual produk kopi asli Gayo. Berikut tabel penjualan produk kopi Gayo Coffee selama bulan September:
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (598, 68, 54, NULL, E'binary_matrix', E'Tentukan apakah pernyataan-pernyataan berikut benar atau salah berdasarkan teks di atas!', E'* Pernyataan 1 benar (terdapat pada kalimat 2).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (599, 68, 54, NULL, E'mcq_single', E'Dalam bacaan tersebut, disebutkan bahwa cemas dan gangguan kecemasan adalah dua hal yang berbeda. Pernyataan yang tepat sebagai penjelas tentang hal tersebut adalah...', E'Kalimat ke-8 menyatakan bahwa gangguan kecemasan akan mengubah cara seseorang memproses emosi dan perilaku serta menimbulkan rasa khawatir berlebihan, yang membedakannya dengan kecemasan normal.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (600, 68, 54, NULL, E'mcq_single', E'Seseorang yang mengalami gangguan kecemasan akan menunjukkan beberapa gejala. Berdasarkan bacaan tersebut, yang **tidak** termasuk gejala yang ditunjukkan oleh penderita gangguan kecemasan adalah....', E'Gejala gangguan kecemasan yang disebutkan pada kalimat (9) meliputi berkeringat, merasa mual (hendak muntah), sulit berkonsentrasi, tekanan darah naik, hingga insomnia. (Catatan: Depresi merupakan dampak jangka panjang jika dibiarkan, bukan gejala fisik langsung).', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (601, 68, 55, NULL, E'mcq_single', E'Berdasarkan bacaan tersebut, seseorang mengalami ASMR apabila....', E'Berdasarkan kalimat kedua teks, istilah ASMR digunakan untuk menggambarkan sensasi kesemutan yang menenangkan yang dialami beberapa orang sebagai respons terhadap audio dan visual tertentu (rangsangan tertentu).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (602, 68, 56, NULL, E'mcq_single', E'Menurut bacaan tersebut, jika kita memasak dengan kompor induksi, dibutuhkan peralatan masak khusus. Pernyataan yang tepat sebagai penjelas hal tersebut adalah......', E'Kalimat kelima teks menyatakan bahwa peralatan masak yang cocok digunakan untuk kompor induksi adalah yang berbahan partikel besi magnet dengan penghantar panas yang baik.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (603, 68, 56, NULL, E'mcq_single', E'Berdasarkan bacaan tersebut, apakah yang menjadi tanda bahwa wajan bisa digunakan pada kompor induksi?', E'Kalimat terakhir teks menyatakan bahwa jika magnet menempel pada bagian bawah wajan saat dites, maka wajan tersebut bisa digunakan pada kompor induksi.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (604, 68, 57, NULL, E'mcq_single', E'Berdasarkan bacaan tersebut, panas pada kompor induksi dihasilkan dari....', E'Kalimat kelima paragraf pertama menyatakan bahwa perputaran arus yang diakibatkan oleh tegangan induksi pada logam tersebut akan menghasilkan panas.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (605, 68, 57, NULL, E'mcq_single', E'Keunggulan kompor induksi berdasarkan bacaan tersebut adalah....', E'Paragraf kedua menyebutkan bahwa keunggulan kompor induksi antara lain permukaan kompor tidak akan terasa panas jika disentuh oleh jari sehingga risiko luka bakar tidak ada.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-20 07:25:55', E'2026-10-22 21:30:15', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (606, 68, 57, NULL, E'mcq_single', E'Pernyataan yang sesuai dengan informasi dalam bacaan tersebut adalah......', E'Kalimat ketiga paragraf pertama menyatakan bahwa medagn magnet memotong atau menabrak alat masak yang digunakan sehingga terjadi tegangan induksi.', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (607, 68, 58, NULL, E'mcq_single', E'Berdasarkan informasi tersebut, manakah pernyataan berikut yang benar?', E'Kalimat kedua teks menyatakan bahwa terkait dengan hal tersebut, diperlukan kapasitas pemerintah dan para pelaku ekonomi untuk mencapai swasembada dan kemandirian ekonomi.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (608, 68, 59, NULL, E'mcq_single', E'Pada bacaan tersebut, penulis menginformasikan bahwa ….…', E'Kalimat kedua teks secara jelas menyatakan bahwa pangan (makanan) menjadi hal yang paling sering menjadi penyebab manusia terpapar BPA.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (609, 68, 60, NULL, E'mcq_single', E'Berdasarkan informasi tersebut, manakah pernyataan berikut yang salah?', E'Pernyataan E bernilai salah karena teks tidak pernah menyatakan bahwa *semua* perusahaan pasti akan tetap bertahan jika manajemennya baik (faktor penentu kelangsungan perusahaan tidak hanya sebatas manajemen yang baik).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
