INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (611, 68, 61, NULL, E'mcq_single', E'Kemampuan Amir Hamzah dalam bahasa Melayu-Indonesia diakui. Hal yang menyebabkannya adalah bahwa beliau.…', E'Kalimat (6) dan (7) menguraikan kepiawaian Amir Hamzah dalam meramu bahasa Melayu-Indonesia hingga menghasilkan suara dan lagu yang unik.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
