INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (613, 68, 63, NULL, E'binary_matrix', E'Berdasarkan bacaan tersebut, dengan adanya peralihan siaran TV analog ke siaran TV digital, akses internet dapat lebih mudah, cepat, dan terjangkau. Pernyataan yang tepat terkait dengan penyebab hal tersebut adalah......', E'Penyiaran digital membuat kanal TV lebih efisien (1 kanal muat 6-12 TV), sehingga menyisakan frekuensi untuk perluasan internet dan ruang internet 5G yang lebih cepat.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (614, 68, 64, NULL, E'mcq_single', E'Berdasarkan teks tersebut, pernyataan manakah yang *tidak* termasuk karakteristik perilaku berpola seseorang yang mengalami *video gaming disorder*?', E'Karakteristik (4) menyebutkan adanya gangguan yang memengaruhi fungsi pribadi, keluarga, sosial, pendidikan, dan hal penting lainnya (tidak secara khusus menyebutkan "memengaruhi psikis penderita" sebagai frasa mutlak karakteristik dalam teks).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (615, 68, 65, NULL, E'binary_matrix', E'Tentukan apakah pernyataan-pernyataan berikut benar atau salah berdasarkan teks di atas!', NULL, 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (616, 68, 65, NULL, E'mcq_single', E'Menurut bacaan tersebut, yang *tidak* termasuk kelainan atau penyakit yang dapat muncul dengan adanya diabetes adalah....', E'Gagal ginjal, retinopati diabetik, gastropati diabetik, dan serangan jantung koroner merupakan kelainan/komplikasi penyakit akibat diabetes. Adapun "cuci rongga perut" adalah bentuk terapi pengganti ginjal, bukan jenis penyakit atau kelainannya.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (617, 68, 65, NULL, E'mcq_single', E'Makna kata *diabetesi* yang paling tepat berdasarkan bacaan tersebut adalah....', E'Pada kalimat (7) disebutkan "pasien diabetes (diabetesi)", yang menunjukkan bahwa istilah *diabetesi* merujuk pada penderita diabetes.', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
