INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (619, 68, 66, NULL, E'mcq_single', E'Dalam teks tersebut, generasi terkini dikatakan sebagai generasi “yatim piatu” karena...', E'Kalimat (2) dan (3) menjelaskan bahwa generasi terkini dijuluki "yatim piatu" karena secara sosiologis hampir seluruh pengetahuan dan *attitude* mereka didapatkan dari gawai dan internet, bukan dari orang tua atau guru.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (620, 68, 66, NULL, E'mcq_single', E'Makna kata *satire* dalam bacaan tersebut adalah....', E'Kata *satire* dalam KBBI bermakna gaya bahasa yang dipakai dalam kesusastraan untuk menyatakan sindiran terhadap suatu keadaan atau seseorang.', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
