INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (623, 68, 67, NULL, E'mcq_single', E'Dalam teks tersebut, terdapat pernyataan “Keberadaan mangrove berkaitan erat dengan tingkat produksi perikanan.” Pernyataan berikut ini yang merupakan penjelas yang tepat atas pernyataan tersebut adalah...', E'Kalimat (11) memberikan penjelasan konkret bahwa daerah-daerah perikanan potensial di Indonesia masih berbatasan langsung dengan hutan mangrove yang luas.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
