INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (625, 68, 68, NULL, E'mcq_single', E'Menurut bacaan, paspor elektronik memiliki keunggulan, yakni...', E'Keunggulan fungsional utama paspor elektronik bagi pelancong adalah penumpang tidak perlu mengantre di konter manual karena bisa langsung menuju *autogate*.', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (626, 68, 68, NULL, E'mcq_single', E'Kekurangan paspor elektronik, sesuai bacaan tersebut, adalah....', E'Paragraf terakhir menggarisbawahi bahwa adanya komponen *chip* menuntut pemilik untuk memberikan perawatan ekstra (dijauhkan dari air, magnet, panas, tidak boleh dilipat/dibanting).', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-20 07:25:55', E'2026-10-20 07:25:55', NULL, NULL, NULL, NULL);
