INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (754, 74, NULL, NULL, E'mcq_single', E'Yang manakah di antara grafik berikut yang menyatakan $y$ sebagai fungsi dari $x$?', E'Suatu relasi menyatakan $y$ sebagai fungsi dari $x$ apabila setiap anggota domain ($x$) memiliki tepat satu pasangan di kodomain ($y$).
