INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (758, 74, NULL, NULL, E'mcq_single', E'Bilangan dalam kotak abu-abu adalah hasil operasi aritmetik semua bilangan di kotak putih. Dengan menggunakan pola yang sama, maka nilai dari $x$ adalah ……
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (759, 74, NULL, NULL, E'mcq_single', E'Seseorang membeli televisi seharga Rp1.000.000,00 sudah termasuk di dalamnya diskon harga 20%. Harga televisi itu sebenarnya adalah …', E'Harga setelah diskon $20\\%$ adalah $80\\%$ dari harga awal ($H_0$):
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (760, 74, NULL, NULL, E'mcq_single', E'Andi melakukan suatu pekerjaan membutuhkan waktu selama 2 jam. Sedangkan Budi mengerjakan pekerjaan yang sama membutuhkan waktu 3 jam. Berapa lama waktu yang diperlukan mereka berdua dalam melakukan pekerjaan tersebut secara bersama-sama?', E'Waktu gabungan ($t$) jika dikerjakan bersama-sama:
