INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (762, 74, NULL, NULL, E'mcq_single', E'Umar memiliki sebidang tanah, $\\frac{2}{5}$ bagian dari tanah yang dimilikinya dia bangun menjadi rumah tinggal, $\\frac{1}{4}$-nya dia jadikan kolam renang dan $\\frac{2}{3}$ dari sisanya dijadikan pekarangan rumah. Jika luas pekarangan rumah Umar $91\\text{ m}^2$, berapa $\\text{m}^2$ luas tanah Umar seluruhnya?', E'Misalkan luas tanah seluruhnya adalah $L$.
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (763, 75, 93, NULL, E'mcq_single', E'Dalam teks tersebut, terdapat pernyataan “Keindahan Sorong dan Raja Ampat, bahkan keindahan alam Indonesia secara umum, bisa terekspos ke dunia global adalah berkah dari kemajuan teknologi saat ini.” Pernyataan berikut ini yang merupakan penjelas yang tepat atas pernyataan tersebut adalah... (*jawapos.com*)', E'Kalimat kedua pada paragraf kedua menjelaskan secara langsung bagaimana kemajuan teknologi (internet dan gawai) mengekspos keindahan alam Indonesia, yaitu dengan menangkap gambar dan video sehingga bisa dibagikan dengan cepat, murah, dan menjangkau jutaan orang dalam waktu yang sangat singkat (A).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-22 06:09:51', E'2026-10-22 06:09:51', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (764, 75, 93, NULL, E'mcq_single', E'Menurut teks tersebut, yang telah memicu ”revolusi” pola komunikasi dan informasi adalah.... (*jawapos.com*)', E'Sesuai kunci sumber adalah A yaitu penyebaran informasi yang cepat (Catatan: Secara tersurat pada kalimat keempat paragraf kedua disebutkan bahwa "kehadiran gawai dan internet sebenarnya telah memicu ''revolusi'' pola komunikasi dan informasi" yang merujuk pada opsi B).', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-22 06:09:51', E'2026-10-22 06:09:51', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (765, 75, 94, NULL, E'mcq_single', E'Inti yang dibahas dalam teks tersebut adalah.... (*dindik.jatimprov.go.id*)', E'Gagasan pokok yang menaungi paragraf pertama dan kedua adalah pentingnya penerapan sistem pendidikan antikorupsi secara terpadu dan sistematis di lembaga pendidikan untuk membekali generasi muda agar menolak korupsi (B).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-22 06:09:51', E'2026-10-22 06:09:51', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (766, 75, 94, NULL, E'binary_matrix', E'Tentukan apakah pernyataan-pernyataan berikut benar atau salah berdasarkan teks di atas! (*dindik.jatimprov.go.id*)', E'* Pernyataan 1 benar (sesuai kalimat 1).', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-22 06:09:51', E'2026-10-22 06:09:51', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (767, 75, 94, NULL, E'binary_matrix', E'Menurut bacaan tersebut, alasan perlunya pendidikan antikorupsi melalui jalur pendidikan adalah.... (*dindik.jatimprov.go.id*)', E'Sesuai kunci sumber merujuk pada kalimat (5), yaitu diperlukan sistem pendidikan antikorupsi yang berisi sosialisasi bentuk-bentuk korupsi, cara pencegahan, pelaporan, dan pengawasan (Catatan: Kalimat 10 juga menyebutkan alasan efektivitas jalur pendidikan karena "lebih tersistem serta hasilnya mudah terukur" pada opsi D).', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-22 06:09:51', E'2026-10-22 06:09:51', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (768, 75, 95, NULL, E'mcq_single', E'Dalam teks tersebut, terdapat pernyataan “Teknologi hibrida pada mobil tidak hanya memberikan kenyamanan dalam berkendara, tetapi juga menghemat bahan bakar.” Pernyataan berikut ini yang merupakan penjelasan yang tepat atas pernyataan tersebut adalah... (*voi.id*)', E'Kalimat ketiga dan keempat menjelaskan alasan penghematan bahan bakar tersebut, yakni sumber daya utama mobil hibrida berupa kombinasi mesin bensin dan generator listrik dengan dukungan baterai membuat konsumsi energi menjadi lebih irit (B).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-22 06:09:52', E'2026-10-22 21:30:15', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (769, 75, 95, NULL, E'mcq_single', E'Kata *hibrida* yang terdapat dalam teks tersebut bermakna.... (*voi.id*)', E'Sesuai kunci sumber soal adalah A karena dalam konteks kalimat pertama teks, teknologi hibrida mengacu pada perpaduan penggerak dari dua sumber energi yang berbeda (energi listrik dan bahan bakar konvensional). Secara leksikal di KBBI, *hibrida* juga bermakna penggabungan/persilangan dua jenis yang berbeda (opsi D).', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-22 06:09:52', E'2026-10-22 21:30:15', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (770, 75, 96, NULL, E'mcq_single', E'Berdasarkan teks tersebut, yang menjadi penyebab enggannya Ivan bersekolah adalah..... (*Van Loon*, Hengki Kumayandi)', E'Pada paragraf ketiga, Ivan menangis dan mengadu kepada ibunya bahwa ia tidak nyaman di sekolah karena teman-temannya mengejek dan mengatainya sebagai "anak Belanda" atau "anak penjajah" (D).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (771, 75, 96, NULL, E'mcq_single', E'Nilai moral yang tercermin dalam cerita tersebut adalah.... (*Van Loon*, Hengki Kumayandi)', E'Nilai moral baik yang ditunjukkan oleh tokoh Ivan ketika menghadapi perundungan di sekolah adalah kejujuran dan keterbukaannya dalam menceritakan masalah yang dialami kepada orang tuanya (ibunya) (A).', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (772, 75, 97, NULL, E'mcq_single', E'Menurut bacaan tersebut, yang menjadi alasan bahwa dimainkannya *game online* oleh anak usia sekolah bukanlah hal yang buruk adalah..... (*brilio.net*)', E'Kalimat kedua pada paragraf kedua menyebutkan secara tersurat bahwa sebagian masyarakat menganggap bermain *game online* bukanlah hal yang buruk karena tujuannya hanyalah untuk kesenangan atau hiburan (C).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (773, 75, 97, NULL, E'mcq_single', E'Dampak buruk dimainkannya *game online* oleh anak usia sekolah berdasarkan bacaan adalah... (*brilio.net*)', E'Pada paragraf ketiga dijelaskan bahwa dampak buruk *game online* adalah membuat anak kecanduan bermain sehingga waktu belajarnya makin berkurang dan timbul rasa malas belajar (D).', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (774, 75, 98, NULL, E'mcq_single', E'Apa inti isi teks tersebut?', E'Sesuai kunci sumber soal adalah A yang merujuk pada fakta pembuka teks bahwa sebagian besar komposisi organ tubuh manusia terdiri atas air (95% otak, 82% darah, 75% jantung, 86% paru-paru, dan 83% ginjal), sehingga keberadaan air sangat penting bagi tubuh.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (775, 75, 98, NULL, E'mcq_single', E'Kekurangan air dapat menyebabkan dehidrasi pada tubuh yang memengaruhi kinerja tubuh dan otak berdasarkan bacaan tersebut adalah.....', E'Pada paragraf kedua dijelaskan bahwa dehidrasi memengaruhi kinerja tubuh dan otak yang mengakibatkan manusia menjadi cepat lupa, sukar menyelesaikan soal matematika sederhana, sulit berkonsentrasi, serta lekas lelah (D).', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (776, 75, 99, NULL, E'binary_matrix', E'Tentukan apakah pernyataan-pernyataan berikut benar atau salah berdasarkan teks di atas! (liputan6.com)', E'* Pernyataan 1 benar (sesuai kalimat 1 dan 5).
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (777, 75, 99, NULL, E'mcq_single', E'Menurut bacaan tersebut, judul yang sesuai untuk melengkapi tulisan tersebut adalah..... (liputan6.com)', E'Teks secara menyeluruh membahas langkah, peran pendidikan tinggi, dan tantangan dalam menciptakan sumber daya manusia (SDM) yang berkualitas tinggi bagi kemajuan bangsa Indonesia, sehingga judul yang paling tepat adalah “Penciptaan SDM Berkualitas di Indonesia” (C).', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (778, 75, 99, NULL, E'mcq_single', E'Berdasarkan bacaan tersebut, kunci kemajuan bangsa melalui penciptaan sumber daya manusia (SDM) yang berkualitas tinggi adalah..... (liputan6.com)', E'Berdasarkan kalimat (1), (2), dan (6), penciptaan SDM berkualitas tinggi sebagai jaminan dan kunci kemajuan masa depan bangsa diwujudkan melalui jalur pendidikan (B).', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (779, 75, 99, NULL, E'mcq_single', E'Yang *bukan* menjadi kunci utama yang harus diwujudkan perguruan tinggi menjadi andal dan berkelas dunia menurut Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi (PAN-RB) ialah... (liputan6.com)', E'Tiga kunci utama yang disampaikan Menteri PAN-RB terdapat pada paragraf pertama dan kedua (kalimat 1–5). Adapun pernyataan pada opsi C terdapat pada kalimat (8) paragraf ketiga yang menjelaskan fungsi pendidikan secara umum setelah pemaparan riset Bank Dunia, sehingga bukan bagian dari tiga poin kunci Menteri PAN-RB.', 1, E'{"labels":["Benar","Salah"]}', 4, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (780, 75, 100, NULL, E'mcq_single', E'Berdasarkan informasi di atas, jika temanmu, Bayu, ingin membeli tiket konser secara individu, berarti ia harus memperhatikan hal-hal berikut, kecuali....', E'Berdasarkan paragraf ketiga, tips membeli tiket dari individu meliputi memastikan tanggal/jadwal konser, tempat, vendor, kewajaran harga tiket yang ditawarkan, serta metode/tata cara pembayaran (menggunakan situs pembayaran aman dan menghindari transfer bank langsung). Pemeriksaan "kode batang pada tiket" (A) tidak disebutkan di dalam teks.', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (781, 75, 100, NULL, E'mcq_single', E'Bacaan di atas bertujuan.....', E'Paragraf pertama membuka dengan fenomena penipuan tiket konser dan diakhiri kalimat pertanyaan "Lalu, bagaimana tips agar kita terhindar dari penipuan tiket konser?", yang kemudian dijawab dengan rincian panduan di paragraf kedua dan ketiga. Dengan demikian, tujuan utama bacaan tersebut adalah memberikan petunjuk yang aman untuk pembaca dalam membeli tiket konser (D).', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (782, 75, 100, NULL, E'mcq_single', E'Saat membeli tiket via *website* dan akan melakukan pembayaran, kamu dikirimkan alamat situs untuk pembayaran tiket. Apa sebaiknya yang perlu dilakukan berdasarkan teks di atas?', E'Berdasarkan poin ke-3 pada paragraf kedua, sebelum melakukan pembayaran di situs web, pembeli harus memastikan alamat web dimulai dengan *https*, karena huruf "s" pada alamat protokol domain tersebut menandakan bahwa situs itu aman (B).', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (783, 75, 101, NULL, E'mcq_single', E'Hal yang dibicarakan dalam teks di atas adalah..... (*harianaceh.co.id*)', E'Gagasan utama teks terletak pada tawaran konsep moderasi beragama oleh Haedar Nashir beserta alasan mengapa sikap moderat tersebut sangat penting bagi kemajemukan Indonesia (B).', 1, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (784, 75, 101, NULL, E'mcq_single', E'Istilah *moderasi beragama* dalam teks di atas bermakna …... (*harianaceh.co.id*)', E'Menurut KBBI, *moderasi* berarti pengurangan kekerasan atau penghindaran keekstreman. Dalam konteks mengatasi radikalisme pada teks, *moderasi beragama* bermakna penghindaran sikap ekstrem dalam beragama (E).', 1, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (785, 75, 101, NULL, E'mcq_single', E'Pernyataan yang *tidak* sesuai dengan teks di atas adalah …... (*harianaceh.co.id*)', E'Kalimat keempat teks menyatakan bahwa "Salah satu faktornya adalah karena bangsa ini disusun oleh begitu banyak suku." Kata *salah satu* menunjukkan masih ada faktor lain, sehingga pernyataan bahwa banyaknya suku merupakan *satu-satunya* faktor moderat (D) tidak sesuai dengan isi teks.', 1, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-22 06:09:52', E'2026-10-22 06:09:52', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (786, 75, NULL, NULL, E'mcq_single', E'Bacalah teks berikut!
