INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (821, 77, NULL, NULL, E'mcq_single', E'Diketahui matriks $A = \\begin{bmatrix} -3 & 8 \\\\ 2 & 4 \\end{bmatrix}$, $B = \\begin{bmatrix} -6 & 1 \\\\ 0 & -1 \\end{bmatrix}$, dan $C = A - B$. Invers dari matriks $C$ adalah....', E'Cari matriks $C = A - B$ terlebih dahulu:
