INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1203, 91, 158, NULL, E'mcq_single', E'(UTBK 2022/TPS/PK/66)
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1204, 91, 159, NULL, E'mcq_single', E'(UTBK 2022/TPS/PK/67 - No. 20) Absis terkecil semua titik potong grafik fungsi $f$ dan $g$ adalah ...', E'Menentukan titik potong dengan menyamakan kedua fungsi: $f(x) = g(x) \\implies 1 - x^2 = 3 - 3x \\implies x^2 - 3x + 2 = 0 \\implies (x - 2)(x - 1) = 0$, sehingga $x = 2$ atau $x = 1$. Maka absis terkecilnya adalah $x = 1$.', 2, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-23 19:25:43', E'2026-10-23 19:25:43', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1205, 91, 159, NULL, E'mcq_single', E'(UTBK 2022/TPS/PK/08 - No. 50) Nilai dari $\\int (g(x) - f(x)) \\, dx$ adalah ...', E'$\\int (g(x) - f(x)) \\, dx = \\int ((3 - 3x) - (1 - x^2)) \\, dx = \\int (x^2 - 3x + 2) \\, dx = \\frac{1}{3}x^3 - \\frac{3}{2}x^2 + 2x + C$.', 2, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-23 19:25:43', E'2026-10-23 19:25:43', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1206, 91, 159, NULL, E'mcq_single', E'(UTBK 2022/TPS/PK/69 - No. 51) Luas daerah di kuadran pertama yang dibatasi oleh grafik fungsi $f$ dan $g$, serta sumbu-$y$ adalah ...', E'Untuk menentukan luas daerah $L$ di kuadran pertama, hitung luas segitiga dikurangi luas daerah di bawah parabola $D$.
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1207, 91, 160, NULL, E'mcq_single', E'(UTBK 2022/TPS/PK/H4/61 - No. 34) Nilai $y$ adalah ...', E'Gunakan rumus suku tengah barisan aritmetika: $U_1 + U_3 = 2U_2 \\implies (y - 3) + 6 = 2(1) \\implies y + 3 = 2 \\implies y = -1$.', 2, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-23 19:25:43', E'2026-10-23 19:25:43', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1208, 91, 160, NULL, E'mcq_single', E'(UTBK 2022/TPS/PK/H4/63 - No. 35) Median dari 20 suku pertama barisan tersebut adalah ...', E'Dari $U_1 + U_3 = 2U_2 \\implies U_1 + 6 = 2(1) \\implies U_1 = -4$ dengan beda $b = 5$. Suku ke-20 adalah $U_{20} = U_1 + 19b = -4 + 19(5) = 91$. Median dari 20 suku pertama: $2Me = U_1 + U_{20} = -4 + 91 = 87 \\implies Me = 43,5$.', 2, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-23 19:25:43', E'2026-10-23 19:25:43', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1209, 91, 161, NULL, E'mcq_single', E'(UTBK 2022/TPS/PK/61 - No. 36) Nilai $a \\times b$ adalah ...', E'Gunakan sifat suku tengah barisan geometri ($y^2 = x \\cdot z$) untuk suku-suku $a, -9, b$: diperoleh $a \\cdot b = (-9)^2 = 81$.', 2, E'{"labels":["Benar","Salah"]}', 1, E'2026-10-23 19:25:43', E'2026-10-23 19:25:43', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1210, 91, 161, NULL, E'mcq_single', E'(UTBK 2022/TPS/PK/62 - No. 37) Hasil bagi suku ke-5 dengan suku ke-2 barisan tersebut adalah ...', E'Dari rumus suku tengah untuk $U_1, U_3, U_5$: $U_1 \\cdot U_5 = U_3^2 \\implies (-1)U_5 = (-9)^2 \\implies U_5 = -81$. Untuk $U_1, U_2, U_3$: $U_2^2 = U_1 \\cdot U_3 = (-1)(-9) = 9 \\implies U_2 = \\pm 3$. Jadi, $\\frac{U_5}{U_2} = \\frac{-81}{3} = -27$ atau $\\frac{U_5}{U_2} = \\frac{-81}{-3} = 27$.', 2, E'{"labels":["Benar","Salah"]}', 2, E'2026-10-23 19:25:43', E'2026-10-23 19:25:43', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1211, 91, 161, NULL, E'mcq_single', E'(UTBK 2022/TPS/PK/63 - No. 38) Hasil pengurangan suku ke-5 oleh suku pertama adalah ...', E'Dari sifat suku tengah barisan geometri $U_1 \\cdot U_5 = U_3^2 \\implies (-1)U_5 = (-9)^2 \\implies U_5 = -81$. Maka $U_5 - U_1 = -81 - (-1) = -80$.', 2, E'{"labels":["Benar","Salah"]}', 3, E'2026-10-23 19:25:43', E'2026-10-23 19:25:43', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1212, 91, NULL, NULL, E'mcq_single', E'(UTBK 2022/TPS/PK/H4/76)
