INSERT INTO "questions" ("id", "assessment_section_id", "question_group_id", "question_bank_id", "type", "prompt", "explanation", "points", "settings", "order", "created_at", "updated_at", "explanation_status", "explanation_error", "explanation_model", "explanation_generated_at") VALUES (1274, 94, 177, NULL, E'mcq_single', E'Mulai 1 Mei 2023, volume minyak goreng merek A ditambahi menjadi 15 liter pada setiap kali pengiriman. Selisih volume minyak goreng merek A yang diterima Toko Maju pada bulan Mei dan April adalah... (UTBK 2023/TPS/PM/Gel.1/04)', E'Toko Maju menerima kiriman minyak goreng dari tiga pemasok untuk dijual kembali dengan jadwal sebagai berikut.
